for(const scenario of ['startup-failure','worker-crash','partial-initialization','provider-failure','timeout','controller-interruption'])test('real restricted rehearsal failure stops and owner cleanup revokes: '+scenario,async()=>{const r=await rehearsalCase(scenario);assert(r.error);assert(r.after.workflows.every(w=>!['assigned','running'].includes(w.status)));assert(r.events.filter(e=>e.providerBoundary).length<=1);assert.equal(r.after.paidExecution,false);});

