for(const scenario of ['stale-release','cleanup-failure'])test('declared harmless fault profile exercises the actual tracked failure: '+scenario,async()=>{const r=await rehearsalCase(scenario);assert(r.error);assert.equal(r.after.approvals[0].status,'revoked');if(scenario==='stale-release')assert.equal(r.events.filter(e=>e.providerBoundary).length,0);else{assert.equal(r.error.shutdownConfirmed,false);assert.equal(r.result,undefined);assert.equal(r.after.workflows[0].stage,'outcome');}});

test('actual supervised restricted worker survives >30s capture and a committed lost renewal reply without task revision injection',async()=>{const r=await rehearsalCase('accepted','lease-lost-reply');assert.ifError(r.error);assert.equal(r.result.status,'verified');assert.equal(r.after.workflows[0].calls,5);assert(r.events.some(e=>e.lostLeaseReply));assert(r.events.some(e=>e.leaseRenewed&&e.attempts===2));assert(r.after.audit.filter(e=>e.type==='lease_renewed').length>=5);assert.equal(r.after.approvals[0].status,'revoked');});
test('actual supervisor owner renewal during delayed sealed Chief context preserves all five native stage contracts',async()=>{const r=await rehearsalCase('accepted','chief-renew-race');assert.ifError(r.error);assert.equal(r.result.status,'verified');const w=r.after.workflows[0],reservation=r.after.reservations.find(x=>x.stage==='chief');assert(reservation.admittedLedgerRevision>reservation.binding.snapshotRevision);assert.equal(w.calls,5);assert.equal(r.after.audit.filter(e=>e.type==='chief_context_sealed').length,1);assert.equal(r.events.filter(e=>e.providerBoundary).length,5);assert.equal(r.after.approvals[0].status,'revoked');});
